using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Xml;using System.Xml.Linq;using System.Collections.Generic;using System.Globalization;using System.Drawing;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Media3D;using System.Windows.Media.Imaging;
public static class ModelRender {
 static double Num(string s){return double.Parse(s,CultureInfo.InvariantCulture);}static string Attr(XElement e,string n){var a=e.Attributes().FirstOrDefault(x=>x.Name.LocalName==n);return a==null?null:a.Value;}
 static Matrix3D Matrix(string text){if(string.IsNullOrWhiteSpace(text))return Matrix3D.Identity;var a=text.Split(new[]{' ','\t','\n'},StringSplitOptions.RemoveEmptyEntries).Select(Num).ToArray();if(a.Length!=12)throw new InvalidDataException("Invalid transform");return new Matrix3D(a[0],a[1],a[2],0,a[3],a[4],a[5],0,a[6],a[7],a[8],0,a[9],a[10],a[11],1);}
 public static Bitmap Render(string file){using(var zip=ZipFile.OpenRead(file)){var docs=new Dictionary<string,XDocument>(StringComparer.OrdinalIgnoreCase);foreach(var entry in zip.Entries.Where(e=>e.FullName.EndsWith(".model",StringComparison.OrdinalIgnoreCase))){if(entry.Length>180*1024*1024)throw new InvalidDataException("Model XML too large");using(var stream=entry.Open())using(var reader=XmlReader.Create(stream,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null}))docs[entry.FullName.TrimStart('/')]=XDocument.Load(reader);}string main=docs.Keys.FirstOrDefault(k=>k.Equals("3D/3dmodel.model",StringComparison.OrdinalIgnoreCase))??docs.Keys.First();var group=new Model3DGroup();int triangles=0;Action<string,string,Matrix3D,int> add=null;add=(part,id,transform,depth)=>{if(depth>20)throw new InvalidDataException("Component nesting too deep");XDocument doc;if(!docs.TryGetValue(part,out doc))throw new InvalidDataException("Missing component");var obj=doc.Descendants().FirstOrDefault(e=>e.Name.LocalName=="object"&&Attr(e,"id")==id);if(obj==null)throw new InvalidDataException("Missing object");var mesh=obj.Elements().FirstOrDefault(e=>e.Name.LocalName=="mesh");if(mesh!=null){var positions=new Point3DCollection();foreach(var v in mesh.Descendants().Where(e=>e.Name.LocalName=="vertex"))positions.Add(transform.Transform(new Point3D(Num(Attr(v,"x")),Num(Attr(v,"y")),Num(Attr(v,"z")))));var indices=new Int32Collection();foreach(var t in mesh.Descendants().Where(e=>e.Name.LocalName=="triangle")){if(++triangles>1500000)throw new InvalidDataException("Model too complex");indices.Add(int.Parse(Attr(t,"v1")));indices.Add(int.Parse(Attr(t,"v2")));indices.Add(int.Parse(Attr(t,"v3")));}var material=new MaterialGroup();material.Children.Add(new DiffuseMaterial(new SolidColorBrush(System.Windows.Media.Color.FromRgb(184,180,169))));material.Children.Add(new SpecularMaterial(new SolidColorBrush(System.Windows.Media.Color.FromRgb(100,96,85)),32));var geo=new GeometryModel3D(new MeshGeometry3D{Positions=positions,TriangleIndices=indices},material){BackMaterial=material};group.Children.Add(geo);}foreach(var component in obj.Descendants().Where(e=>e.Name.LocalName=="component")){string target=Attr(component,"path");if(target==null)target=part;else if(target.StartsWith("/"))target=target.TrimStart('/');else target=new Uri(new Uri("http://model/"+part),target).AbsolutePath.TrimStart('/');var m=Matrix(Attr(component,"transform"));m.Append(transform);add(target,Attr(component,"objectid"),m,depth+1);}};foreach(var item in docs[main].Descendants().Where(e=>e.Name.LocalName=="item")){if(Attr(item,"printable")=="0")continue;add(main,Attr(item,"objectid"),Matrix(Attr(item,"transform")),0);}if(group.Children.Count==0)throw new InvalidDataException("No mesh found");return RenderGroup(group);}} public static Bitmap RenderGroup(Model3DGroup group){var bounds=group.Bounds;var center=new Point3D(bounds.X+bounds.SizeX/2,bounds.Y+bounds.SizeY/2,bounds.Z+bounds.SizeZ/2);double radius=Math.Sqrt(bounds.SizeX*bounds.SizeX+bounds.SizeY*bounds.SizeY+bounds.SizeZ*bounds.SizeZ)/2;if(radius<=0)throw new InvalidDataException("Empty mesh");var direction=new Vector3D(1.2,-1.8,1.0);direction.Normalize();var world=new Model3DGroup();world.Children.Add(group);world.Children.Add(new AmbientLight(System.Windows.Media.Color.FromRgb(72,72,72)));world.Children.Add(new DirectionalLight(System.Windows.Media.Color.FromRgb(220,216,205),new Vector3D(-1,1,-2)));world.Children.Add(new DirectionalLight(System.Windows.Media.Color.FromRgb(70,81,95),new Vector3D(1,-1,-.3)));var viewport=new Viewport3D{Camera=new OrthographicCamera(center+direction*radius*4,-direction,new Vector3D(0,0,1),radius*2.35)};viewport.Children.Add(new ModelVisual3D{Content=world});var host=new Grid{Background=new SolidColorBrush(System.Windows.Media.Color.FromRgb(225,225,223)),Width=640,Height=640};var right=Vector3D.CrossProduct(-direction,new Vector3D(0,0,1));right.Normalize();var up=Vector3D.CrossProduct(right,-direction);up.Normalize();double low=double.PositiveInfinity;foreach(GeometryModel3D shape in group.Children){var mesh=(MeshGeometry3D)shape.Geometry;foreach(var v in mesh.Positions)low=Math.Min(low,Vector3D.DotProduct(v-center,up));}double bottom=320-low*640/(radius*2.35);var shadow=new System.Windows.Shapes.Ellipse{Width=radius>0?300:300,Height=55,Fill=new SolidColorBrush(System.Windows.Media.Color.FromArgb(90,30,30,30)),VerticalAlignment=VerticalAlignment.Bottom,Margin=new Thickness(0,0,0,Math.Max(5,640-bottom-30)),Effect=new System.Windows.Media.Effects.BlurEffect{Radius=24}};host.Children.Add(shadow);host.Children.Add(viewport);host.Measure(new System.Windows.Size(640,640));host.Arrange(new Rect(0,0,640,640));host.UpdateLayout();var image=new RenderTargetBitmap(640,640,96,96,PixelFormats.Pbgra32);image.Render(host);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using(var mem=new MemoryStream()){encoder.Save(mem);mem.Position=0;using(var bmp=new Bitmap(mem))return new Bitmap(bmp);}}
}